const getMetricSize = (value: string) => {
  const length = value.replace(/\s/g, "").length;
  if (value.startsWith("£")) return "metric-wide";
  if (length >= 6) return "metric-wide";
  if (length <= 2) return "metric-compact";
  if (length <= 6) return "metric-regular";
  return "metric-wide";
};

